class MultilingualTextNormalizer:
    """Conservative, script-safe normalization for languages without bespoke rules."""

    def __call__(self, text: str) -> str:
        text = unicodedata.normalize("NFC", text).lower()
        text = re.sub(r"[<\[][^>\]]*[>\]]", "", text)
        text = re.sub(r"\(([^)]+?)\)", "", text)
        text = text.replace("​", "").replace("﻿", "")
        # Preserve Unicode marks: they carry meaning in scripts such as Arabic.
        text = regex.sub(r"[\p{P}\p{S}]+", " ", text)
        return re.sub(r"\s+", " ", text).strip()


@dataclass(frozen=True)
class LanguageSupport:
    """A supported language and the normalization level available for it.

    ``tier`` is one of:

    - ``"dedicated"``: a normalizer written and reviewed for this language.
    - ``"script"``: no dedicated class yet, but the language shares a script
      with a dedicated normalizer that is reused as-is (for example Marathi
      reuses the Devanagari normalizer, without Hindi's number/TTS tuning).
    - ``"generic"``: only conservative, script-safe cleanup is applied; no
      language-specific rules exist.
    """

    code: str
    name: str
    factory: Callable[..., Callable[[str], str]]
    capabilities: tuple[str, ...]
    tier: str


