def _supports_option(factory: Callable[..., Callable[[str], str]], option: str) -> bool:
    """Return whether ``factory``'s constructor accepts a given keyword option."""
    try:
        parameters = inspect.signature(factory).parameters
    except (TypeError, ValueError):
        return False
    if option in parameters:
        return True
    return any(p.kind is inspect.Parameter.VAR_KEYWORD for p in parameters.values())


def get_normalizer(language: str, **options) -> Callable[[str], str]:
    """Return a fresh normalizer for a BCP-47 tag, ISO 639-1 code, or language name.

    ``language`` accepts plain codes (``"hi"``), BCP-47 tags with a region or
    script subtag (``"hi-IN"``, ``"zh-Hans"``, ``"es-ES"``), and English
    language names (``"hindi"``). Only the primary language subtag drives
    selection: a region/script suffix is accepted but does not currently
    change which normalizer is returned. Keyword options such as
    ``tts_mode=True`` are validated against the selected normalizer and raise
    ``ValueError`` if it doesn't accept them, instead of being silently
    ignored.
    """
    key = language.lower().replace("_", "-").split("-", 1)[0]
    key = LANGUAGE_ALIASES.get(key, key)
    entry = LANGUAGE_REGISTRY.get(key)
    if entry is None:
        supported = ", ".join(sorted(LANGUAGE_REGISTRY))
        raise ValueError(f"Unsupported language: {language!r}. Supported codes: {supported}")
    unsupported_options = sorted(name for name in options if not _supports_option(entry.factory, name))
    if unsupported_options:
        raise ValueError(
            f"{entry.name} normalizer does not support option(s): {', '.join(unsupported_options)}"
        )
    return entry.factory(**options)


def supported_languages() -> tuple[LanguageSupport, ...]:
    """Return the language registry in ISO-code order."""

    return tuple(LANGUAGE_REGISTRY[code] for code in sorted(LANGUAGE_REGISTRY))
